 1.8178590993659487, 2.497859099365948, 0.07624746575887673, 0.0012474657588766869, 0.3012474657588767, 0.6762474657588766, 2.029247465758877, 2.7012474657588763, 0.1383070033641625, 0.06330700336416245, 0.3633070033641624, 0.7383070033641623, 2.0913070033641628, 2.7633070033641625, 0.12384445820716831, 0.04884445820716829, 0.3488444582071682, 0.7238444582071681, 2.0768444582071686, 2.7488444582071683, 0.07624746575887673, 0.0012474657588766869, 0.3012474657588767, 0.6762474657588766, 2.029247465758877, 2.7012474657588763, -0.01818253607345395, -0.09318253607345398, 0.20681746392654593, 0.5818174639265459, 1.9348174639265463, 2.6068174639265456, -0.08304928241031526, -0.1580492824103153, 0.14195071758968464, 0.5169507175896846, 1.8699507175896852, 2.5419507175896845];
    private static readonly double[,] Pts = {{0.1, -0.9, 0.2}, {1.3, 0.6, 1.9}, {2.95, 2.1, 3.0}, {0.4, -0.2, 1.5}, {2.2, 0.0, 2.7}, {1.0, 1.0, 1.0}};

    private static NdArray Values => new((double[])V.Clone(), 7, 6, 6);
    [Fact]
    public void Methods_MatchScipy()
    {
        AllClose([0.0859525406303761, 1.6130439209142167, 1.7508568010758911, 0.9966559020950481, 2.405035522146223, 0.7177902825976883], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Linear).Evaluate(Pts), 1e-12, "linear");
        AllClose([0.0, 1.7621080382182703, 1.8699507175896852, 0.9966559020950481, 3.154172017348893, 0.501521391647851], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Nearest).Evaluate(Pts), 1e-12, "nearest");
        AllClose([0.0806920824620098, 1.6284321704218983, 1.727807909031052, 0.9966559020950481, 2.4006065187937295, 0.6603752181839636], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Pchip).Evaluate(Pts), 1e-12, "pchip");
        AllClose([0.0859525406303761, 1.6130439209142167, 1.7508568010758916, 0.9966559020950481, 2.4050355221462234, 0.7177902825976883], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Slinear).Evaluate(Pts), 1e-10, "slinear exact");
        AllClose([0.08595254063037609, 1.6130439209142164, 1.7508568010758911, 0.9966559020950481, 2.405035522146223, 0.7177902825976881], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Slinear).Evaluate(Pts), 1e-4, "slinear vs scipy default solver");
        AllClose([0.07310431317504415, 1.6316931552886487, 1.7187872762567076, 0.9966559020950481, 2.3986162828848894, 0.6544662793299505], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Cubic).Evaluate(Pts), 1e-10, "cubic exact");
        AllClose([0.07310714017948534, 1.631699055525895, 1.7187903638068165, 0.9966645463932018, 2.3986150355218867, 0.6544524065674269], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Cubic).Evaluate(Pts), 1e-4, "cubic vs scipy default solver");
        AllClose([0.07183046199353048, 1.6311711730621499, 1.7188057710010383, 0.9966559020950492, 2.4018851477927954, 0.6546533675275613], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Quintic).Evaluate(Pts), 1e-10, "quintic exact");
        AllClose([0.0718644723720384, 1.631148497855873, 1.718807932438661, 0.996645298342579, 2.4019034512492112, 0.6546884902409056], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Quintic).Evaluate(Pts), 1e-4, "quintic vs scipy default solver");
        AllClose([-6.595368998357288e-15, 4.280701227515893e-15, -1.4210854715202004e-14, -4.1234377023968705e-15, -1.4988010832439613e-15, 5.412337245047638e-16], new RegularGridInterpolator([Gx, Gy, Gz], Values, RegularGridMethod.Cubic).Evaluate(Pts, nu: [1, 0, 2]), 1e-9, "cubic derivative");
        var o = new double[,] { { 3.5, 0.0, 1.0 }, { -0.5, 0.0, 1.0 } };
        AllClose([double.NaN, double.NaN], new RegularGridInterpolator([Gx, Gy, Gz], Values, boundsError: false).Evaluate(o), 0, "nan fill");
        AllClose([-0.30164266471699713, -0.03781660775998155], new RegularGridInterpolator([Gx, Gy, Gz], Values, boundsError: false, fillValue: null).Evaluate(o), 1e-12, "extrapolate");
        Assert.Throws<ArgumentException>(() => new RegularGridInterpolator([Gx, Gy, Gz], Values).Evaluate(o));
    }

    [Fact]
    public void DescendingGrid_TrailingValues_2D_MatchScipy()
    {
        double[] gyd = [2.2, 1.7, 1.0, 0.5, -0.2, -1.0];
        var v2 = new double[7 * 6];
        var w = new double[7 * 6 * 2];
        for (var i = 0; i < 7; i++)
            for (var j = 0; j < 6; j++)
            {
                var v = Math.Sin(Gx[i] + gyd[j]);
                v2[i * 6 + j] = v;
                w[(i * 6 + j) * 2] = v; w[(i * 6 + j) * 2 + 1] = v * v;
            }
        var q = new NdArray([0.3, 0.1, 2.5, 1.9, 1.2, -0.5], 3, 2);
        var r = new RegularGridInterpolator([Gx, gyd], new NdArray(w, 7, 6, 2)).Evaluate(q);
        Assert.Equal([3, 2], r.Shape.ToArray());
        AllClose([0.35991333745787324, 0.2444095719747715, -0.8562543603566453, 0.7653309399445661, 0.5907647480353836, 0.4570463917041476], r.ToArray(), 1e-12, "trailing");
        AllClose([0.3890691151480137, -0.951490837979163, 0.6503863448025635], new RegularGridInterpolator([Gx, gyd], new NdArray(v2, 7, 6), RegularGridMethod.Cubic).Evaluate(q).ToArray(), 1e-10, "cubic descending");
    }

    [Fact]
    public void RectBivariateSpline_And_Bisplev_MatchScipy()
    {
        var xx = new double[6];
        var yy = new double[7];
        for (var i = 0; i < 6; i++) xx[i] = i / 5.0;
        for (var j = 0; j < 7; j++) yy[j] = 2.0 * j / 6;
        var zz = new double[42];
        for (var i = 0; i < 6; i++)
            for (var j = 0; j < 7; j++) zz[i * 7 + j] = Math.Sin(3 * xx[i]) + Math.Cos(2 * yy[j]) + xx[i] * yy[j];
        var rb = new RectBivariateSpline(xx, yy, new NdArray(zz, 6, 7));
        AllClose([0.0, 0.0, 0.0, 0.0, 0.4, 0.6000000000000001, 1.0, 1.0, 1.0, 1.0], rb.GetKnots().Tx, 1e-15, "tx");
        AllClose([1.0000000000000002, 1.0187058152769937, 0.4885186259023112, -0.4480535950205481, -1.1293717481561634, -1.012919588074914, -0.6536436208636122, 1.4086770392936192, 1.45701248420024, 0.9712697392700024, 0.09395677760640399, -0.5281021162699534, -0.3672055117442594, 0.021700085096672837, 1.9751962720092928, 2.0679761613603627, 1.6489000830967897, 0.8604760103220795, 0.32730600533461246, 0.5548692765269739, 0.9882193178123484, 2.049406504649739, 2.2162604680748803, 1.9082955009224185, 1.2680195762958582, 0.8829977194565376, 1.2216721017600112, 1.7290962171194597, 1.5474811990429176, 1.7587796069125041, 1.5174813064267076, 0.9660942706890366, 0.6699613027386055, 1.0753023517087437, 1.6271709115126383, 1.1411200080598674, 1.382048045559083, 1.1851941895177336, 0.6930664130393195, 0.45619270434814874, 0.9059781977627319, 1.4874763871962553], rb.GetCoeffs(), 1e-11, "coeffs");
        AllClose([1.332070324815609, 0.9589380418579306, 1.2779519947182147, 1.1798927333787452, 0.5387727253188782], rb.Ev([0.13, 0.5, 0.97, 1.5, -1], [0.2, 1.1, 1.9, 0.5, 0.5]), 1e-12, "ev (clamped outside)");
        AllClose([2.9547355385524576, 1.3124397178964684, -1.0597773206491288], rb.Ev([0.13, 0.5, 0.97], [0.2, 1.1, 1.9], 1, 0), 1e-11, "dx");
        AllClose([-3.8269848047995114, 2.33546886517405, 3.7965293965677858], rb.Ev([0.13, 0.5, 0.97], [0.2, 1.1, 1.9], 0, 2), 1e-10, "dyy");
        AllClose([1.1536560186651845, -0.01859171315914981, -0.42346876856741167, 1.979948526155387, 1.1577007943310529, 1.1528237389227918], rb.Evaluate([0.1, 0.6], [0.3, 1.0, 1.8]).ToArray(), 1e-12, "grid");
        Close(0.943815791656902, rb.Integral(0.1, 0.8, 0.3, 1.7), 1e-12, "integral");
        Close(1.9489009765041434, rb.Integral(-1, 3, 0, 2), 1e-12, "integral clipped");
        AllClose([1.0000000000000016, 0.999999999999997, 0.999999999999988], rb.PartialDerivative(1, 1).Ev([0.13, 0.5, 0.97], [0.2, 1.1, 1.9]), 1e-10, "partial derivative spline");
        var rb2 = new RectBivariateSpline(xx, yy, new NdArray(zz, 6, 7), kx: 2, ky: 1);
        AllClose([1.2845889460408442, 0.9888765904727528, 1.3261337767923638], rb2.Ev([0.13, 0.5, 0.97], [0.2, 1.1, 1.9]), 1e-12, "kx=2, ky=1");
        var (tx, ty) = rb.GetKnots();
        AllClose([1.1536560186651845, -0.01859171315914981, -0.42346876856741167, 1.979948526155387, 1.1577007943310529, 1.1528237389227918], Interpolate.Bisplev([0.1, 0.6], [0.3, 1.0, 1.8], (tx, ty, rb.GetCoeffs(), 3, 3)).ToArray(), 1e-12, "bisplev");
        AllClose([0.9999999999999964, 1.0000000000000033, 1.0000000000000004, 0.9999999999999922, 1.0000000000000018, 1.0000000000000033], Interpolate.Bisplev([0.1, 0.6], [0.3, 1.0, 1.8], (tx, ty, rb.GetCoeffs(), 3, 3), 1, 1).ToArray(), 1e-10, "bisplev dxdy");
    }

    [Fact]
    public void Interpn_MatchesScipy()
    {
        var xi = new NdArray([0.1, -0.9, 0.2, 1.3, 0.6, 1.9], 2, 3);
        AllClose([0.0859525406303761, 1.6130439209142167], Interpolate.Interpn([Gx, Gy, Gz], Values, xi).ToArray(), 1e-12, "linear");
        AllClose([0.0, 1.7621080382182703], Interpolate.Interpn([Gx, Gy, Gz], Values, xi, RegularGridMethod.Nearest).ToArray(), 0, "nearest");
        var v2 = new double[42];
        for (var i = 0; i < 7; i++)
            for (var j = 0; j < 6; j++) v2[i * 6 + j] = Math.Sin(Gx[i]) * Math.Cos(Gy[j]);
        var q = new NdArray([0.3, 0.1, 2.5, 1.9, 1.2, -0.5, 4.0, 0.0], 4, 2);
        AllClose([0.2936745623705616, -0.19302352405994164, 0.8244755087583696, double.NaN], Interpolate.Interpn([Gx, Gy], new NdArray(v2, 7, 6), q, RegularGridMethod.Splinef2d, boundsError: false).ToArray(), 1e-12, "splinef2d");
    }
}
